"use strict";(self.webpackChunkwww=self.webpackChunkwww||[]).push([[97890],{93221:(e,t,h)=>{h.r(t),h.d(t,{assets:()=>r,contentTitle:()=>i,default:()=>c,frontMatter:()=>o,metadata:()=>a,toc:()=>d});var s=h(31085),n=h(71184);const o={sidebar_position:18,slug:"/bible/John/John_18",title:"John 18",hide_table_of_contents:!0},i="John",a={id:"bible/John/John 18",title:"John 18",description:"Chapter 18",source:"@site/docs/bible/John/John 18.md",sourceDirName:"bible/John",slug:"/bible/John/John_18",permalink:"/bibleNotes/docs/bible/John/John_18",draft:!1,unlisted:!1,editUrl:"https://github.com/ozkey/bibleNotes/tree/main/packages/www/docs/bible/John/John 18.md",tags:[],version:"current",sidebarPosition:18,frontMatter:{sidebar_position:18,slug:"/bible/John/John_18",title:"John 18",hide_table_of_contents:!0},sidebar:"bibleSidebar",previous:{title:"John 17",permalink:"/bibleNotes/docs/bible/John/John_17"},next:{title:"John 19",permalink:"/bibleNotes/docs/bible/John/John_19"}},r={},d=[{value:"Chapter 18",id:"chapter-18",level:2}];function l(e){const t={h1:"h1",h2:"h2",p:"p",...(0,n.R)(),...e.components},{BibleText:h}=t;return h||function(e,t){throw new Error("Expected "+(t?"component":"object")+" `"+e+"` to be defined: you likely forgot to import, pass, or provide it.")}("BibleText",!0),(0,s.jsxs)(s.Fragment,{children:[(0,s.jsx)(t.h1,{id:"john",children:"John"}),"\n",(0,s.jsx)(t.h2,{id:"chapter-18",children:"Chapter 18"}),"\n",(0,s.jsx)(t.p,{children:"The history of the passion of Christ."}),"\n",(0,s.jsx)(h,{verse:1,children:"When Jesus had said these things, he went forth with his disciples over the brook Cedron, where there was a garden, into which he entered with his disciples."}),"\n",(0,s.jsx)(h,{verse:2,children:"And Judas also, who betrayed him, knew the place: because Jesus had often resorted thither together with his disciples."}),"\n",(0,s.jsx)(h,{verse:3,children:"Judas therefore having received a band of soldiers and servants from the chief priests and the Pharisees, cometh thither with lanterns and torches and weapons."}),"\n",(0,s.jsx)(h,{verse:4,children:"Jesus therefore, knowing all things that should come upon him, went forth and said to them: Whom seek ye?"}),"\n",(0,s.jsx)(h,{verse:5,children:"They answered him: Jesus of Nazareth. Jesus saith to them: I am he. And Judas also, who betrayed him, stood with them."}),"\n",(0,s.jsx)(h,{verse:6,children:"As soon therefore as he had said to them: I am he; they went backward and fell to the ground."}),"\n",(0,s.jsx)(h,{verse:7,children:"Again therefore he asked them: Whom seek ye? And they said: Jesus of Nazareth."}),"\n",(0,s.jsx)(h,{verse:8,children:"Jesus answered: I have told you that I am he. If therefore you seek me, let these go their way,"}),"\n",(0,s.jsx)(h,{verse:9,children:"That the word might be fulfilled which he said: Of them whom thou hast given me, I have not lost any one."}),"\n",(0,s.jsx)(h,{verse:10,children:"Then Simon Peter, having a sword, drew it and struck the servant of the high priest and cut off his right ear. And the name of thee servant was Malchus."}),"\n",(0,s.jsx)(h,{verse:11,children:"Jesus therefore said to Peter: Put up thy sword into the scabbard. The chalice which my father hath given me, shall I not drink it?"}),"\n",(0,s.jsx)(h,{verse:12,children:"Then the band and the tribune and the servants of the Jews took Jesus and bound him."}),"\n",(0,s.jsx)(h,{verse:13,children:"And they led him away to Annas first, for he was father-in-law to Caiphas, who was the high priest of that year."}),"\n",(0,s.jsx)(h,{verse:14,children:"Now Caiphas was he who had given the counsel to the Jews: That it was expedient that one man should die for the people."}),"\n",(0,s.jsx)(h,{verse:15,children:"And Simon Peter followed Jesus: and so did another disciple. And that disciple was known to the high priest and went in with Jesus into the court of the high priest."}),"\n",(0,s.jsx)(h,{verse:16,children:"But Peter stood at the door without. The other disciple therefore, who was known to the high priest, went out and spoke to the portress and brought in Peter."}),"\n",(0,s.jsx)(h,{verse:17,children:"The maid therefore that was portress saith to Peter: Art not thou also one of this man's disciple? He saith I am not."}),"\n",(0,s.jsx)(h,{verse:18,children:"Now the servants and ministers stood at a fire of coals, because it was cold, and warmed themselves. And with them was Peter also, standing and warming himself."}),"\n",(0,s.jsx)(h,{verse:19,children:"The high priest therefore asked Jesus of his disciples and of his doctrine."}),"\n",(0,s.jsx)(h,{verse:20,children:"Jesus answered him: I have spoken openly to the world. I have always taught in the synagogue and in the temple, whither all the Jews resort: and in secret I have spoken nothing."}),"\n",(0,s.jsx)(h,{verse:21,children:"Why askest thou me? Ask them who have heard what I have spoken unto them. Behold they know what things I have said."}),"\n",(0,s.jsx)(h,{verse:22,children:"And when he had said these things, one of the servants standing by gave Jesus a blow, saying: Answerest thou the high priest so?"}),"\n",(0,s.jsx)(h,{verse:23,children:"Jesus answered him: If I have spoken evil, give testimony of the evil; but if well, why strikest thou me?"}),"\n",(0,s.jsx)(h,{verse:24,children:"And Annas sent him bound to Caiphas the high priest."}),"\n",(0,s.jsx)(h,{verse:25,children:"And Simon Peter was standing and warming himself. They said therefore to him: Art not thou also one of his disciples? He denied it and said: I am not."}),"\n",(0,s.jsx)(h,{verse:26,children:"One of the servants of the high priest (a kinsman to him whose ear Peter cut off) saith to him: Did not I see thee in the garden with him?"}),"\n",(0,s.jsx)(h,{verse:27,children:"Again therefore Peter denied: and immediately the cock crew."}),"\n",(0,s.jsx)(h,{verse:28,children:"Then they led Jesus from Caiphas to the governor's hall. And it was morning: and they went not into the hall, that they might not be defiled, but that they might eat the pasch."}),"\n",(0,s.jsx)(h,{verse:29,children:"Pilate therefore went out to them, and said: What accusation bring you against this man?"}),"\n",(0,s.jsx)(h,{verse:30,children:"They answered and said to him: If he were not a malefactor, we would not have delivered him up to thee."}),"\n",(0,s.jsx)(h,{verse:31,children:"Pilate therefore said to them: Take him you, and judge him according to your law. The Jews therefore said to him: It is not lawful for us to put any man to death."}),"\n",(0,s.jsx)(h,{verse:32,children:"That the word of Jesus might be fulfilled, which he said, signifying what death he should die."}),"\n",(0,s.jsx)(h,{verse:33,children:"Pilate therefore went into the hall again and called Jesus and said to him: Art thou the king of the Jews?"}),"\n",(0,s.jsx)(h,{verse:34,children:"Jesus answered: Sayest thou this thing of thyself, or have others told it thee of me?"}),"\n",(0,s.jsx)(h,{verse:35,children:"Pilate answered: Am I a Jew? Thy own nation and the chief priests have delivered thee up to me. What hast thou done?"}),"\n",(0,s.jsx)(h,{verse:36,children:"Jesus answered: My kingdom is not of this world. If my kingdom were of this world, my servants would certainly strive that I should not be delivered to the Jews: but now my kingdom is not from hence."}),"\n",(0,s.jsx)(h,{verse:37,children:"Pilate therefore said to him: Art thou a king then? Jesus answered: Thou sayest that I am a king. For this was I born, and for this came I into the world; that I should give testimony to the truth. Every one that is of the truth heareth my voice."}),"\n",(0,s.jsx)(h,{verse:38,children:"Pilate saith to him: What is truth? And when he said this, he went out again to the Jews and saith to them: I find no cause in him."}),"\n",(0,s.jsx)(h,{verse:39,children:"But you have a custom that I should release one unto you at the Pasch. Will you, therefore, that I release unto you the king of the Jews?"}),"\n",(0,s.jsx)(h,{verse:40,children:"Then cried they all again, saying: Not this man, but Barabbas. Now Barabbas was a robber."})]})}function c(e={}){const{wrapper:t}={...(0,n.R)(),...e.components};return t?(0,s.jsx)(t,{...e,children:(0,s.jsx)(l,{...e})}):l(e)}},71184:(e,t,h)=>{h.d(t,{R:()=>i,x:()=>a});var s=h(14041);const n={},o=s.createContext(n);function i(e){const t=s.useContext(o);return s.useMemo((function(){return"function"==typeof e?e(t):{...t,...e}}),[t,e])}function a(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(n):e.components||n:i(e.components),s.createElement(o.Provider,{value:t},e.children)}}}]);